def syms(cells):
    s=set()
    for f in [lambda r,c:(r,c),lambda r,c:(r,-c),lambda r,c:(-r,c),lambda r,c:(-r,-c),
              lambda r,c:(c,r),lambda r,c:(c,-r),lambda r,c:(-c,r),lambda r,c:(-c,-r)]:
        s.add(tuple(sorted(f(r,c) for r,c in cells)))
    # normalize each
    out=set()
    for t in s:
        r0=min(a for a,_ in t); c0=min(b for _,b in t)
        out.add(tuple(sorted((a-r0,b-c0) for a,b in t)))
    return out
